import type { Metadata } from "next";
import { getPublicEnv } from "@/lib/env";

/**
 * Social card generated by src/app/opengraph-image.tsx. A page's `openGraph`
 * object replaces the root one, so the file-based image must be referenced
 * explicitly here or it is dropped.
 */
const socialImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Yamin: the marketing that knows itself.",
};

export function createPageMetadata({
  title,
  description,
  path,
}: {
  title: string;
  description: string;
  path: string;
}): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title,
      description,
      url: path,
      siteName: getPublicEnv().siteName,
      locale: "en_US",
      type: "website",
      images: [socialImage],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [socialImage],
    },
  };
}
